query.sparql:
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Salt_Lake_City dbp:timeZone?uri }

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
SELECT DISTINCT?uri WHERE {?uri dct:subject dbc:Assassins_of_Julius_Caesar }

PREFIX dbpedia2: <http://dbpedia.org/property/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Frank_Herbert dbpedia2:birthplace?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?capacity WHERE {
  { dbr:Estádio_dos_Bestas dbo:ground?ground.
   ?ground dbo:populationTotal?capacity }
  UNION
  { dbr:Estádio_dos_Bestas dbp:capacity?capacity } }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?uri WHERE {
 ?uri dct:subject dbc:Countries_in_Europe ; 
  dbo:governmentType dbr:Constitutional_monarchy
}

SELECT DISTINCT?uri WHERE {{
 ?uri a <http://dbpedia.org/ontology/Airport>.
 ?uri <http://dbpedia.org/ontology/location> <http://dbpedia.org/resource/California>.
}}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?string WHERE { res:Angela_Merkel dbp:birthDate?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Berlin dbo:mayor?uri }

SELECT DISTINCT?uri WHERE {
 ?uri a <http://dbpedia.org/ontology/Country>.
 ?uri <http://dbpedia.org/ontology/currency> <http://dbpedia.org/resource/Euro>.
} UNION {
 ?uri <http://dbpedia.org/property/currencyCode> "EUR"@en.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX yago: <http://dbpedia.org/class/yago/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?uri
WHERE {
 ?uri rdf:type yago:MonarchsOfTheUnitedKingdom ;
        dbo:spouse [dbo:birthPlace res:Germany]
}

PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dct: <http://purl.org/dc/terms/>
SELECT DISTINCT?uri WHERE {
  dbc:United_States dbc:States_of_the_United_States ; 
  dct:subject?uri ; 
  dct:date?x.
  FILTER (?x = (xsd:date("2022-12-06")^^xsd:date) )
} ORDER BY DESC(?x) LIMIT 1

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?String WHERE { res:Millipede dbp:class?String }

PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT?string WHERE { dbpedia:Forbes foaf:homepage?string }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Vincent_van_Gogh dbo:publisher?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:K2 dbo:highest?uri }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?date WHERE { res:Finland dbp:membership_date?date }

PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri WHERE {
  <http://dbpedia.org/resource/Lovesick_(1983_film)> dbo:starring?uri.
 ?uri dbo:instanceOf <http://dbpedia.org/class/yago/AnglophoneActorsInTheFrenchFilmLovesick>.
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT?nm WHERE { dbr:Baghdad rdfs:label?nm.}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Berlin dbo:postalCode?string.}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {{
 ?uri dbo:occupation "Surfer" ; dbo:birthPlace dbr:Australia.
}}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE {?uri dbo:location?state.?state rdfs:label?label. FILTER (lang(?label) = "en" && STRSTARTS(?label, "Pennsylvania")) }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX res: <http://dbpedia.org/resource/>
SELECT?years
WHERE {
  res:Ford_Model_T dbo:productionStartDate?start;
          dbo:productionEndYear?end.
  BIND ( xsd:integer( year(xsd:date(?end)) - year(xsd:date(?start)) ) AS?years ) }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT xsd:date(?date) WHERE { res:Carlo_Giuliani dbp:date?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?uri?string WHERE { dbr:Abraham_Lincoln onto:spouse?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?s WHERE { 
 ?s dct:subject dbc:Missions_to_the_Sun ; 
  rdf:type dbo:Spacecraft.
}

SELECT DISTINCT?uri WHERE {
 ?uri a <http://dbpedia.org/ontology/City>.
 ?uri <http://dbpedia.org/ontology/country> <http://dbpedia.org/resource/Germany>.
 ?uri <http://dbpedia.org/ontology/populationTotal>?population.
  FILTER (?population > 250000).
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?number WHERE { res:IBM onto:revenue?number.}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Yenisei_River dbp:locatedIn?uri }

SELECT DISTINCT?uri WHERE {
 ?uri a <http://dbpedia.org/ontology/Automobile>.
 ?uri <http://dbpedia.org/ontology/locationCountry> <http://dbpedia.org/resource/Germany>
}

SELECT DISTINCT?uri WHERE {{
 ?uri a <http://dbpedia.org/ontology/Astronaut>.
 ?uri <http://dbpedia.org/ontology/nationality> <http://dbpedia.org/resource/People's_Republic_of_China>.
}} UNION {
 ?uri a <http://dbpedia.org/ontology/Astronaut>.
 ?uri <http://dbpedia.org/ontology/nationality> <http://dbpedia.org/resource/China>.
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Aldi dbp:founder?uri }

PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?uri WHERE {?uri a onto:Book ; dbpedia:author <http://dbpedia.org/resource/Danielle_Steel> }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
 ?uri a dbo:Company ;
       dbo:industry dbr:Aerospace ;
       dbo:industry dbr:Medical.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?parent WHERE {
  res:Queen_Victoria dbo:parent?parent
}

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:>
ASK WHERE {?uri dct:subject dbc:Castles_in_the_United_States }

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri
WHERE {
  { <http://dbpedia.org/resource/Rhine> dbo:locatedIn?uri }
  UNION
  {?uri dbo:locatedOn <http://dbpedia.org/resource/Rhine> }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT * WHERE { res:Elizabeth_II dbo:father?uri.?uri dbo:familyName "Windsor"@en }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?uri WHERE {
 ?uri rdf:type dbo:President ;
        dct:subject dbc:Presidents_of_the_United_States ;
        dbo:birthDate?termEnd.
  FILTER ( ( year(now()) - year(?termEnd) ) <= 20 )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?n WHERE {?n dbo:wavelength "450-495" }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX yago: <http://dbpedia.org/class/yago/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?uri
WHERE {
 ?uri rdf:type dbo:Person ;
        dbo:birthPlace?x ;
        dbo:deathPlace?x
}

PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT?s WHERE {
  <http://dbpedia.org/resource/Teenage_Mutant_Ninja_Turtles> <http://dbpedia.org/property/teamMember>?x.
 ?x foaf:givenName?s
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?year WHERE { res:Jack_Wolfskin dbo:established?year }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?string WHERE { res:Texas dbp:governor?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?uri
WHERE {
 ?uri a dbo:MilitaryConflict ;
        dbo:place dbr:San_Antonio ;
        dbo:date?date
  FILTER (?date >= "1836-05-01T00:00:00Z"^^xsd:dateTime )
  FILTER (?date <= "1836-05-24T00:00:00Z"^^xsd:dateTime )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia/>
SELECT DISTINCT?uri WHERE { res:Munch dbo:artist res:The_Scream }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?date WHERE {
  res:De_Beers dbo:foundingDate?date }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Juan_Carlos_I_of_Spain dbo:spouse?x.?x dbo:familyMember?y.?y dbo:parent?uri }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT?Novelist WHERE {?Novel dbr:title "A Song of Ice and Fire" ; dbp:author?Novelist. }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT?uri) AS?count)
WHERE {
  {{?uri dbo:location dbr:South_Carolina.
   ?uri rdf:type (dbo:River | dbo:Lake).
  } UNION {
   ?uri dct:subject dbc:Rivers_in_South_Carolina.
   ?uri dct:subject dbc:Lakes_in_South_Carolina.
  }}
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT?uri WHERE {
 ?uri dct:subject dbc:States_of_the_United_States ;
    rdf:type dbo:AdministrativeRegion ;
    dbo:populationTotal?area.
  FILTER (?area > 0)
} ORDER BY DESC(?area) LIMIT 1
